import { SNAPSHOT_SCHEMA_PATTERN, SNAPSHOT_TABLES } from '@aftercare/domain';
import { z } from 'zod';
import { principalSchema } from './primitives.ts';
import { instantSchema, int64TextSchema, sha256HexSchema } from './wire.ts';

/** Generated by the database; a caller can never supply one. */
export const snapshotSchemaNameSchema = z
  .string()
  .regex(SNAPSHOT_SCHEMA_PATTERN, 'not a generated snapshot schema name');

export const snapshotTableSchema = z.enum(SNAPSHOT_TABLES);

export const snapshotColumnNameSchema = z
  .string()
  .regex(/^[a-z][a-z0-9_]{0,62}$/, 'not a snapshot column name');

/**
 * Bounds of one snapshot creation. The maxima equal the hard ceilings inside
 * aftercare_control.create_snapshot(); the database refuses anything above.
 */
export const snapshotLimitsSchema = z.strictObject({
  /** Wait for the session-level coordination lock (and for any lock during the copy). */
  lockTimeoutMs: z.number().int().min(1).max(60_000).default(5_000),
  /** Any single statement, including the copy itself. */
  statementTimeoutMs: z.number().int().min(1).max(120_000).default(30_000),
  /** The whole creation: lock wait plus transaction. */
  totalTimeoutMs: z.number().int().min(1).max(300_000).default(60_000),
  maxRowsPerTable: z.number().int().min(1).max(1_000_000).default(200_000),
  maxTotalRows: z.number().int().min(1).max(2_000_000).default(500_000),
  maxTotalBytes: z.number().int().min(1).max(1_073_741_824).default(268_435_456),
});

export const createSnapshotRequestSchema = z.strictObject({
  caseId: z.uuid(),
  limits: snapshotLimitsSchema.prefault({}),
});

export const snapshotScopeTableSchema = z.strictObject({
  table: snapshotTableSchema,
  columns: z.array(snapshotColumnNameSchema).min(1),
  keyColumns: z.array(snapshotColumnNameSchema).min(1),
  rowCount: int64TextSchema,
  digest: sha256HexSchema,
});

export const snapshotRecordSchema = z.strictObject({
  snapshotId: z.uuid(),
  caseId: z.uuid(),
  sourceEnvironment: z.string().min(1),
  schemaName: snapshotSchemaNameSchema,
  baseWatermark: int64TextSchema,
  status: z.enum(['published', 'dropped']),
  createdAt: instantSchema,
  createdBy: z.string(),
  droppedAt: instantSchema.nullable(),
  versions: z.strictObject({
    schema: z.string().min(1),
    audit: z.number().int(),
    adapter: z.strictObject({ id: z.string(), version: z.number().int() }),
    digestFormat: z.number().int(),
    templateSetDigest: sha256HexSchema,
  }),
  limits: z.strictObject({
    maxRowsPerTable: int64TextSchema,
    maxTotalRows: int64TextSchema,
    maxTotalBytes: int64TextSchema,
  }),
  scope: z.array(snapshotScopeTableSchema),
  totalRows: int64TextSchema,
  totalBytes: int64TextSchema,
  contentDigest: sha256HexSchema,
  /** Observations made in the creating transaction. Recorded as found, never "fixed". */
  integrity: z.strictObject({
    commitCount: int64TextSchema,
    maxCommitSeq: int64TextSchema,
    commitsBeyondWatermark: int64TextSchema,
    commitsWithoutOperations: int64TextSchema,
    operationsWithoutCommit: int64TextSchema,
    commitLedgerMatchesWatermark: z.boolean(),
  }),
});

export type SnapshotLimits = z.output<typeof snapshotLimitsSchema>;
export type CreateSnapshotRequest = z.input<typeof createSnapshotRequestSchema>;
export type SnapshotScopeTable = z.output<typeof snapshotScopeTableSchema>;
export type SnapshotRecord = z.output<typeof snapshotRecordSchema>;

/** Why a snapshot was not created or dropped. Nothing was published when one is returned. */
export const SNAPSHOT_FAILURE_CODES = [
  'invalid_argument',
  'protocol_violation',
  'stale_snapshot',
  'case_not_found',
  'quota_exceeded',
  'snapshot_unavailable',
  'lock_timeout',
  'statement_timeout',
  'total_timeout',
] as const;
export type SnapshotFailureCode = (typeof SNAPSHOT_FAILURE_CODES)[number];

/** Where the failure happened: waiting for the session lock, or inside the transaction. */
export type SnapshotStage = 'coordination_lock' | 'transaction';

export interface SnapshotFailure {
  readonly code: SnapshotFailureCode;
  readonly stage: SnapshotStage;
  readonly message: string;
}

export type SnapshotOutcome =
  | { readonly ok: true; readonly snapshot: SnapshotRecord }
  | { readonly ok: false; readonly failure: SnapshotFailure };

export const createCaseInputSchema = z.strictObject({
  principal: principalSchema,
  title: z
    .string()
    .max(200)
    .refine((title) => title.trim() !== '', 'case title must not be blank'),
});

export type CreateCaseInput = z.output<typeof createCaseInputSchema>;

export const caseRecordSchema = z.strictObject({
  caseId: z.uuid(),
  title: z.string(),
  openedBy: z.string(),
  openedAt: instantSchema,
});

export type CaseRecord = z.output<typeof caseRecordSchema>;
